// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 val) public {
        val = bound(val, 1, type(uint256).max);
        address actor = address(0xABCD);
        vm.prank(actor);
        c.SetMinSum(val);
        assertTrue(c.MinSum() == val, "MinSum must be set to the supplied value");
    }
}
